// Configuración del bucket de analítica: Block Public Access, política de bucket y ACL.
export const configuracion = {
  blockPublicAccess: {
    bucket: {
      BlockPublicAcls: true,
      IgnorePublicAcls: true,
      BlockPublicPolicy: true,
      RestrictPublicBuckets: true,
    },
  },
  bucketPolicy: {
    Version: "2012-10-17",
    Statement: [
      {
        Effect: "Allow",
        Principal: { AWS: "arn:aws:iam::111122223333:role/analitica" },
        Action: "s3:GetObject",
        Resource: "arn:aws:s3:::amzn-s3-demo-bucket/*",
      },
    ],
  },
  objectOwnership: "BucketOwnerEnforced",
};

spec.code:
const resultado = aws.s3access.evaluateS3Access({
  ...configuracion,
  request: {
    principal: { type: "anonymous" },
    action: "s3:GetObject",
    resource: { arn: "arn:aws:s3:::amzn-s3-demo-bucket/informe.csv", accountId: "111122223333" },
  },
});
assert.strictEqual(resultado.allowed, false, "Una solicitud anónima no debe poder leer el objeto");

const efectivo = aws.s3access.effectiveBlockPublicAccess(configuracion.blockPublicAccess);
assert.deepStrictEqual(efectivo, {
  BlockPublicAcls: true,
  IgnorePublicAcls: true,
  BlockPublicPolicy: true,
  RestrictPublicBuckets: true,
});

const resultado = aws.s3access.evaluateS3Access({
  ...configuracion,
  request: {
    principal: { type: "iam", arn: "arn:aws:iam::111122223333:role/analitica", accountId: "111122223333" },
    action: "s3:GetObject",
    resource: { arn: "arn:aws:s3:::amzn-s3-demo-bucket/informe.csv", accountId: "111122223333" },
  },
});
assert.strictEqual(resultado.allowed, true, "El rol analitica debe poder leer los objetos");

const resultado = aws.s3access.evaluateS3Access({
  ...configuracion,
  request: {
    principal: {
      type: "iam",
      arn: "arn:aws:iam::222222222222:role/externo",
      accountId: "222222222222",
      identityPolicies: [
        { Version: "2012-10-17", Statement: [{ Effect: "Allow", Action: "s3:GetObject", Resource: "*" }] },
      ],
    },
    action: "s3:GetObject",
    resource: { arn: "arn:aws:s3:::amzn-s3-demo-bucket/informe.csv", accountId: "111122223333" },
  },
});
assert.strictEqual(resultado.allowed, false, "Un rol que la política no nombra no debe poder leer");

const resultado = aws.s3access.evaluateS3Access({
  ...configuracion,
  request: {
    principal: { type: "iam", arn: "arn:aws:iam::111122223333:role/analitica", accountId: "111122223333" },
    action: "s3:PutObject",
    resource: { arn: "arn:aws:s3:::amzn-s3-demo-bucket/informe.csv", accountId: "111122223333" },
  },
});
assert.strictEqual(resultado.allowed, false, "La política solo concede s3:GetObject");

