        Principal: { AWS: "arn:aws:iam::222222222222:role/auditoria" },
        Action: "s3:GetObject",
        Resource: "arn:aws:s3:::amzn-s3-demo-facturas/*",
      },
      {
        Effect: "Allow",
        Principal: { AWS: "arn:aws:iam::222222222222:role/auditoria" },
        Action: "s3:ListBucket",
        Resource: "arn:aws:s3:::amzn-s3-demo-facturas",
      },
    ],
  },
  objectOwnership: "BucketOwnerEnforced",
};

spec.code:
const efectivo = aws.s3access.effectiveBlockPublicAccess(configuracion.blockPublicAccess);
assert.deepStrictEqual(efectivo, {
  BlockPublicAcls: true,
  IgnorePublicAcls: true,
  BlockPublicPolicy: true,
  RestrictPublicBuckets: true,
});

const resultado = aws.s3access.evaluateS3Access({
  ...configuracion,
  request: {
    principal: { type: "anonymous" },
    action: "s3:GetObject",
    resource: { arn: "arn:aws:s3:::amzn-s3-demo-facturas/2026/enero.pdf", accountId: "111122223333" },
  },
});
assert.strictEqual(resultado.allowed, false, "Una solicitud anónima no debe poder leer");

const resultado = aws.s3access.evaluateS3Access({
  ...configuracion,
  request: {
    principal: {
      type: "iam",
      arn: "arn:aws:iam::222222222222:role/auditoria",
      accountId: "222222222222",
      identityPolicies: [
        { Version: "2012-10-17", Statement: [{ Effect: "Allow", Action: ["s3:GetObject", "s3:ListBucket", "s3:PutObject", "s3:DeleteObject"], Resource: "*" }] },
      ],
    },
    action: "s3:GetObject",
    resource: { arn: "arn:aws:s3:::amzn-s3-demo-facturas/2026/enero.pdf", accountId: "111122223333" },
  },
});
assert.strictEqual(resultado.allowed, true, "El rol de auditoría debe poder leer los objetos");

const resultado = aws.s3access.evaluateS3Access({
  ...configuracion,
  request: {
    principal: {
      type: "iam",
      arn: "arn:aws:iam::222222222222:role/auditoria",
      accountId: "222222222222",
      identityPolicies: [
        { Version: "2012-10-17", Statement: [{ Effect: "Allow", Action: ["s3:GetObject", "s3:ListBucket", "s3:PutObject", "s3:DeleteObject"], Resource: "*" }] },
      ],
    },
    action: "s3:ListBucket",
    resource: { arn: "arn:aws:s3:::amzn-s3-demo-facturas", accountId: "111122223333" },
  },
});
assert.strictEqual(resultado.allowed, true, "El rol de auditoría debe poder listar el bucket");

for (const accion of ["s3:PutObject", "s3:DeleteObject"]) {
  const resultado = aws.s3access.evaluateS3Access({
  ...configuracion,
  request: {
    principal: {
      type: "iam",
      arn: "arn:aws:iam::222222222222:role/auditoria",
      accountId: "222222222222",
      identityPolicies: [
        { Version: "2012-10-17", Statement: [{ Effect: "Allow", Action: ["s3:GetObject", "s3:ListBucket", "s3:PutObject", "s3:DeleteObject"], Resource: "*" }] },
      ],
    },
    action: accion,
    resource: { arn: "arn:aws:s3:::amzn-s3-demo-facturas/2026/enero.pdf", accountId: "111122223333" },
  },
});
  assert.strictEqual(resultado.allowed, false, "No debe permitirse " + accion);
}

const resultado = aws.s3access.evaluateS3Access({
  ...configuracion,
  request: {
    principal: {
      type: "iam",
      arn: "arn:aws:iam::333333333333:role/auditoria",
      accountId: "333333333333",
      identityPolicies: [
        { Version: "2012-10-17", Statement: [{ Effect: "Allow", Action: ["s3:GetObject", "s3:ListBucket", "s3:PutObject", "s3:DeleteObject"], Resource: "*" }] },
      ],
    },
    action: "s3:GetObject",
    resource: { arn: "arn:aws:s3:::amzn-s3-demo-facturas/2026/enero.pdf", accountId: "111122223333" },
  },
});
assert.strictEqual(resultado.allowed, false, "Solo el rol de la cuenta 222222222222 puede leer");

