  ],
};

solution.code:
// Servicio de almacenamiento que elige un asistente para cinco casos. Corrige la elección equivocada.
export const eleccion = {
  casos: [
    { necesidad: "Alojar los recursos estáticos de un sitio web como objetos", servicio: "s3" },
    { necesidad: "Dar un disco local a una instancia de EC2 y tomar copias puntuales", servicio: "ebs" },
    { necesidad: "Compartir por NFS los mismos archivos entre varias instancias de EC2", servicio: "efs" },
    { necesidad: "Exponer archivos locales por SMB guardándolos como objetos en S3", servicio: "gateway" },
    { necesidad: "Centralizar los respaldos de varios servicios en un solo plan", servicio: "backup" },
  ],
};

spec.code:
const fila = eleccion.casos.find((f) => f.necesidad.startsWith("Compartir por NFS"));
assert.ok(fila, "debe existir la fila de los archivos compartidos");
assert.strictEqual(fila.servicio, "efs");

for (const fila of eleccion.casos) {
  assert.ok(["s3", "ebs", "efs", "gateway", "backup"].includes(fila.servicio), fila.necesidad + " tiene un servicio no válido");
}

const esperado = {
  "Alojar los recursos estáticos de un sitio web como objetos": "s3",
  "Dar un disco local a una instancia de EC2 y tomar copias puntuales": "ebs",
  "Exponer archivos locales por SMB guardándolos como objetos en S3": "gateway",
  "Centralizar los respaldos de varios servicios en un solo plan": "backup",
};
for (const [necesidad, servicio] of Object.entries(esperado)) {
  const fila = eleccion.casos.find((f) => f.necesidad === necesidad);
  assert.ok(fila, necesidad + " debe seguir existiendo");
  assert.strictEqual(fila.servicio, servicio);
}
